package net.civeira.phylax.features.document.template.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.document.template.domain.Template;
import net.civeira.phylax.features.document.template.domain.gateway.TemplateCursor;
import net.civeira.phylax.features.document.template.domain.gateway.TemplateFilter;

class TemplateSlider extends Slider<Template> {

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final TemplateFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<TemplateFilter, TemplateCursor, Iterator<Template>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  TemplateSlider(final Iterator<Template> multi, final int limit,
      final BiFunction<TemplateFilter, TemplateCursor, Iterator<Template>> gateway,
      final TemplateFilter filter, final TemplateCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param templates
   * @param limit
   * @return
   */
  @Override
  public Iterator<Template> next(List<Template> templates, int limit) {
    Template last = templates.get(templates.size() - 1);
    TemplateCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
